package com.prospr.repository; import java.util.*; import org.springframework.data.mongodb.repository.MongoRepository; import com.prospr.model.FamilyMember; public interface FamilyMemberRepository extends MongoRepository<FamilyMember,String>{ List<FamilyMember> findByOwnerId(String ownerId); List<FamilyMember> findByHouseholdId(String householdId); Optional<FamilyMember> findByActivationTokenHash(String activationTokenHash); }
